-- 000030_rename_authenticator_icon_light_to_icon.up.sql
-- Ensure authenticator_aaguids has single 'icon' column and remove redundant 'icon_dark'
-- Sourced from https://support.yubico.com/s/article/YubiKey-hardware-FIDO2-AAGUIDs

DO $$
BEGIN
    -- Rename icon_light to icon if icon_light exists and icon does not
    IF EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_name = 'authenticator_aaguids' AND column_name = 'icon_light'
    ) AND NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_name = 'authenticator_aaguids' AND column_name = 'icon'
    ) THEN
        ALTER TABLE authenticator_aaguids RENAME COLUMN icon_light TO icon;
    END IF;

    -- Drop icon_dark if it exists
    IF EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_name = 'authenticator_aaguids' AND column_name = 'icon_dark'
    ) THEN
        ALTER TABLE authenticator_aaguids DROP COLUMN icon_dark;
    END IF;

    -- Clean up legacy icon columns on web_authn_credentials if any exist
    IF EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_name = 'web_authn_credentials' AND column_name = 'icon_light'
    ) THEN
        ALTER TABLE web_authn_credentials DROP COLUMN icon_light;
    END IF;

    IF EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_name = 'web_authn_credentials' AND column_name = 'icon_dark'
    ) THEN
        ALTER TABLE web_authn_credentials DROP COLUMN icon_dark;
    END IF;

    IF EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_name = 'web_authn_credentials' AND column_name = 'icon'
    ) THEN
        ALTER TABLE web_authn_credentials DROP COLUMN icon;
    END IF;
END $$;

-- Remove non-official / preview / pre-release Yubico entries if previously seeded
DELETE FROM authenticator_aaguids WHERE aaguid IN (
        '2772ce93-eb4b-4090-8b73-330f48477d73',
        '3124e301-f14e-4e38-876d-fbeeb090e7bf',
        '34f5766d-1536-4a24-9033-0e294e510fb0',
        '58276709-bb4b-4bb3-baf1-60eea99282a7',
        '5b0e46ba-db02-44ac-b979-ca9b84f5e335',
        '62e54e98-c209-4df3-b692-de71bb6a8528',
        '760eda36-00aa-4d29-855b-4012a182cdeb',
        '7dab85a5-d16d-4eaf-a7ef-4c1385b151c5',
        '9806a2c8-c0da-478e-b4ca-620005d34182',
        '9e66c661-e428-452a-a8fb-51f7ed088acf',
        '9eb7eabc-9db5-49a1-b6c3-555a802093f4',
        'ce6bf97f-9f69-4ba7-9032-97adc6ca5cf1',
        'd2fbd093-ee62-488d-9dad-1e36389f8826'
);

-- Seed official Yubico hardware authenticators (70 entries)
ON CONFLICT (aaguid) DO UPDATE SET name = EXCLUDED.name, icon = EXCLUDED.icon, updated_at = NOW();
